 for(const e of this.entities){Object.assign(e,this.spawnPoint(e),{dead:false,hp:100,maxHp:100,mana:120,shield:0,status:{},buffs:{},cd:[0,0,0,0],burn:null,channeling:false,roundKills:0,roundProjectiles:0,roundDamage:0,roundHealing:0,roundObjectives:0,attackCd:0,reloadUntil:0,path:null,wp:1,vx:0,vz:0,reactUntil:undefined,retreatUntil:0,task:'集结',burstShots:0,contributors:{},zip:null,recallAt:0,orbChannel:null,lastDamage:-99});e.weapon=e.carryGun||'classic';e.armor=e.carryArmor||0;const w=GUNS[e.weapon];e.mag=w.mag;e.reserve=w.mag*4;e.range=w.range;e.rate=1/w.rate;}
 const carrier=this.attackingTeam===0?this.player:this.entities.find(e=>e.team===this.attackingTeam&&e.slot===0);this.spike.carrier=carrier.id;this.spike.x=carrier.x;this.spike.z=carrier.z;this.draft={gun:this.player.carryGun||'classic',armor:'keep'};
