 ready(){if(this.phase!=='buy'||this.quote()>this.player.wallet)return false;const p=this.player,cost=this.quote();p.wallet-=cost;this.equip(p,this.draft.gun,this.draft.armor);for(const e of this.entities){if(e.kind!=='hero'||e.player)continue;const owned=GUNS[e.carryGun],budget=e.wallet;const reserve=budget>=2000?400:0;const priorities=e.hero===3?['phantom','bulldog','spectre','stinger','ghost','classic']:['vandal','guardian','spectre','stinger','ghost','classic'];const id=priorities.find(id=>GUNS[id].price<=budget-reserve)||'classic';const chosen=owned&&owned.price>=GUNS[id].price?owned.id:id;const gunCost=chosen===e.carryGun?0:GUNS[chosen].price;const left=budget-gunCost,armor=left>=1000?'heavy':left>=400?'light':'keep';e.wallet-=gunCost+BUY_ARMOR[armor];this.equip(e,chosen,armor);}this.phase='live';this.emit('roundStart',{round:this.round+1,role:this.role});return true;}
