 damage(t,n,source,opts={}){if(this.phase!=='live'||!this.active(t)||source?.team===t.team)return 0;if(t.player&&this.time<(this.playerProtectionUntil||0))return 0;if(source?.team===1&&t.team===0)n*=({easy:.45,normal:.8,hard:1}[this.difficulty]||1);const before=t.hp+t.shield+(t.armor||0);if(opts.skill||opts.dot)n*=.22;const absorb=Math.min(t.armor||0,n*.66);if(absorb){t.armor-=absorb;n-=absorb;}const hpDamage=super.damage(t,n,source,opts);const actual=Math.max(0,before-t.hp-t.shield-(t.armor||0));if(actual>0){if(source?.kind==='hero')source.roundDamage=(source.roundDamage||0)+actual;if(t.player||source?.player){this.combatLog.push({at:this.time,amount:Math.round(actual),source:source?.id,hero:source?.hero,weapon:source?.weapon||null,target:t.id,skill:!!(opts.skill||opts.dot)});if(this.combatLog.length>80)this.combatLog.shift();}if(t.player&&t.dead)this.lastDeath={at:this.time,hero:source?.hero,weapon:source?.weapon||null,skill:!!(opts.skill||opts.dot),incoming:this.combatLog.filter(e=>e.target===t.id&&this.time-e.at<8).reduce((n,e)=>n+e.amount,0)};}return hpDamage;}
