 cast(e,i){if(this.phase!=='live'||e.channeling)return false;const ok=super.cast(e,i);if(ok&&e.hero===4&&i===3)for(const a of this.entities)if(a.kind==='hero'&&a.team===e.team)a.shield=Math.min(a.shield,60);return ok;}
