 kill(t,s){if(t.dead)return;if(t.kind==='hero'&&t.weapon&&t.weapon!=='knife')this.drops.push({id:this.nextId++,x:t.x,z:t.z,gun:t.weapon,mag:t.mag,reserve:t.reserve,expires:this.time+40});if(this.channel?.id===t.id){if(this.channel.type==='defuse')this.spike.defuseProgress=this.spike.defuseProgress>=3.5?3.5:0;this.channel=null;t.channeling=false;}if(t.kind==='hero'&&this.spike?.state==='carried'&&this.spike.carrier===t.id){Object.assign(this.spike,{state:'dropped',carrier:null,x:t.x,z:t.z});this.emit('spikeDrop',{x:t.x,z:t.z});}super.kill(t,s);t.respawn=Infinity;}
