 const site=SITES.find(site=>dist(e,site)<=site.r);const planting=s.state==='carried'&&s.carrier===e.id&&!!site;const defusing=s.state==='planted'&&e.team===this.defendingTeam&&dist(e,s)<2.8;const can=(planting||defusing)&&held&&Math.hypot(e.vx||0,e.vz||0)<.7&&this.time-(e.lastDamage??-99)>.16&&e.reloadUntil<=this.time;
 if(!can){if(this.channel?.id===e.id){if(this.channel.type==='defuse')s.defuseProgress=s.defuseProgress>=3.5?3.5:0;this.channel=null;}e.channeling=false;return;}
 if(this.channel&&this.channel.id!==e.id)return;const type=planting?'plant':'defuse';if(!this.channel)this.channel={id:e.id,type,progress:type==='defuse'?s.defuseProgress:0,total:type==='plant'?4:7,site:site?.name};e.channeling=true;this.channel.progress+=dt;if(type==='defuse')s.defuseProgress=this.channel.progress;
