 passSpike(){if(this.phase!=='live'||this.player.dead||this.player.channeling||this.spike.state!=='carried'||this.spike.carrier!==this.player.id)return false;const ally=this.entities.filter(e=>e.kind==='hero'&&e.team===0&&!e.player&&!e.dead&&dist(e,this.player)<7&&this.los(e,this.player)).sort((a,b)=>dist(a,this.player)-dist(b,this.player))[0];if(!ally)return false;this.spike.carrier=ally.id;this.order={kind:'auto',at:this.time};this.emit('notice',{text:'Spike 已交给队友 · 你可以先手开路或侧翼掩护'});return true;}
