 if(s.state==='planted'&&team===this.defendingTeam){const defuser=friends.find(a=>this.channel?.type==='defuse'&&this.channel.id===a.id)||friends.slice().sort((a,b)=>dist(a,s)-dist(b,s))[0];goal=defuser===e?s:nearestFloor({x:s.x+(e.slot%2?1:-1)*6,z:s.z+(e.slot-2)*2});const urgent=s.remaining<10;const visible=this.enemies(e,13).some(t=>t.kind==='hero'&&this.los(e,t));if(e===defuser&&dist(e,s)<2.6&&(!visible||urgent)){e.task='拆除 Spike';this.objectiveAction(e,true,dt);if(e.channeling)return;}else if(e===defuser)e.task='回防拆包';else e.task='掩护拆包';}
 else if(team===this.attackingTeam){if(s.state==='planted'){goal=nearestFloor({x:s.x+(e.slot%2?1:-1)*6,z:s.z+(e.slot-2)*2});e.task='交叉看包';}else if(s.state==='dropped'){goal=s;e.task='夺回 Spike';}else{goal=order||site;e.task=carrier===e?'持包推进':e.hero===4?'支援持包':'协同推进';if(carrier&&!carrier.player&&e!==carrier&&!order&&dist(e,carrier)>10)goal=carrier;if(carrier?.player&&e!==carrier&&!order&&dist(e,carrier)>12)goal=carrier;if(carrier===e){const plantSite=SITES.find(a=>dist(e,a)<a.r-.5);if(plantSite){e.task='安装 Spike';this.objectiveAction(e,true,dt);if(e.channeling)return;}}}}
