 const dropped=this.drops.find(d=>GUNS[d.gun].price>GUNS[e.weapon].price&&dist(d,e)<4&&this.los(e,d));if(dropped){this.interact(e);return;}
 if(e.hero===4){const wounded=friends.filter(a=>a!==e&&a.hp<60&&dist(a,e)<15).sort((a,b)=>a.hp-b.hp)[0];if(wounded&&!e.channeling&&s.state!=='planted'){goal=wounded;e.task='支援伤员';}}
